// ExtSummary is the Extensions row closed.
func ExtSummary(e ExtView) string {
	if e.Busy != "" {
		return "applying"
	}
	if n := len(extLines(e.Extensions)); n > 0 {
		return strconv.Itoa(n) + " listed"
	}
	return "none"
}

// extLines are the names of a one-per-line list.
func extLines(text string) []string {
	var out []string
	for l := range strings.SplitSeq(text, "\n") {
		if l = strings.TrimSpace(l); l != "" {
			out = append(out, l)
		}
	}
	return out
}

